To add testing functionality, we'll create a simple test that:

1. Submits a contact form (creating a lead in Odoo).
2. Verifies that the lead was created successfully.
3. Deletes the created lead afterward.

Here’s how you can structure the test:

```javascript
import Odoo from 'odoo-await';
import { test } from 'tap';  // Assume you're using 'tap' for testing

async function zrpPlugin(fastify, options) {
  try {
    const zrp = new Odoo({
      baseUrl: options.baseUrl || 'http://portal.exatel.co.id',
      port: options.port || 8069,
      db: options.db || 'zeniverse',
      username: 'exa',
      password: 'exa',
    });

    await zrp.connect();
    fastify.decorate('zrp', zrp);
    fastify.log.info(`ZRP client is initialized:\n${JSON.stringify(zrp, null, 2)}`);

    fastify.post('/contactus', async (request, reply) => {
      const { name, email, company_name, mobile, services, message } = request.body;

      if (!name || !email || !message || !services) {
        return reply.status(400).send({ error: 'Name, email, services, and message are required' });
      }

      try {
        const leadId = await zrp.create('crm.lead', {
          name: `exatel.co.id - Contact from ${name}`,
          contact_name: name,
          email_from: email,
          partner_name: company_name,
          mobile: mobile,
          description: `${services}\n${message}`,
          type: 'lead',
        });

        fastify.log.info(`Contact form submitted successfully: ${leadId}`);
        return reply.send({ message: 'Contact form submitted successfully', leadId });
      } catch (error) {
        fastify.log.error('Failed to submit contact form:', error);
        return reply.status(500).send({ error: 'Failed to submit contact form' });
      }
    });
  } catch (error) {
    fastify.log.error('Failed to initialize ZRP client:', error);
    throw new Error('ZRP client initialization failed');
  }
}

// Test case for creating and deleting a lead
test('Contact form submission test', async (t) => {
  const fastify = require('fastify')();
  await zrpPlugin(fastify, {});

  // Mock request data
  const requestData = {
    name: 'John Doe',
    email: 'john.doe@example.com',
    company_name: 'Doe Industries',
    mobile: '+123456789',
    services: 'Consulting',
    message: 'Looking for consulting services',
  };

  // Step 1: Create a lead
  const response = await fastify.inject({
    method: 'POST',
    url: '/contactus',
    payload: requestData,
  });

  const responseData = JSON.parse(response.payload);
  t.equal(response.statusCode, 200, 'Contact form submission should return 200');
  t.ok(responseData.leadId, 'Lead ID should be returned');

  const leadId = responseData.leadId;

  // Step 2: Delete the lead to clean up
  try {
    await fastify.zrp.delete('crm.lead', [leadId]);
    t.pass('Lead deleted successfully');
  } catch (error) {
    t.fail(`Failed to delete lead: ${error.message}`);
  }

  t.end();
});
```

