```javascript
import Odoo from 'odoo-await';

async function zrpPlugin(fastify, options) {
  try {
    // Initialize the Odoo client with baseUrl and port
    const zrp = new Odoo({
      baseUrl: options.baseUrl || 'http://zenix.id',
      port: options.port || 47200,
    });

    // Decorate Fastify with the zrp client instance
    fastify.decorate('zrp', zrp);
    fastify.log.info(`ZRP client is initialized:\n${JSON.stringify(zrp, null, 2)}`);

    // Log available methods in the Odoo client instance
    const methods = Object.getOwnPropertyNames(Odoo.prototype);
    fastify.log.info(`ZRP client methods:\n${JSON.stringify(methods, null, 2)}`);

    // Create a 'contactus' endpoint
    fastify.post('/contactus', async (request, reply) => {
      const { name, email, message } = request.body;

      // Validate that the required fields are provided
      if (!name || !email || !message) {
        return reply.status(400).send({ error: 'Name, email, and message are required' });
      }

      try {
        // Example: Save the contact form submission to Odoo (assuming a model 'crm.lead' for simplicity)
        const leadId = await zrp.create('crm.lead', {
          name: `Contact from ${name}`,
          contact_name: name,
          email_from: email,
          description: message,
        });

        fastify.log.info(`Contact form submitted successfully: ${leadId}`);
        return reply.send({ message: 'Contact form submitted successfully', leadId });
      } catch (error) {
        fastify.log.error('Failed to submit contact form:', error);
        return reply.status(500).send({ error: 'Failed to submit contact form' });
      }
    });

  } catch (error) {
    fastify.log.error('Failed to initialize ZRP client:', error);
    throw new Error('ZRP client initialization failed');
  }
}

// Export the plugin directly
export default zrpPlugin;
```

