The error you are encountering, `AVV_ERR_PLUGIN_EXEC_TIMEOUT`, indicates that Fastify expects the plugin to either complete its initialization within a certain time frame or to call the `done()` function (or resolve the Promise) to signal that the plugin has finished loading. Since we are dealing with asynchronous tasks, we need to ensure that the Fastify plugin resolves its operations properly.

To fix this, we'll make sure the plugin's lifecycle completes correctly by ensuring the test and the plugin initialization are handled properly. You can return the plugin as a resolved promise when it's done, or use Fastify's `register` functionality properly in the asynchronous context.

### Updated Code with Proper Async Handling

```javascript
import Odoo from 'odoo-await';

async function zrpPlugin(fastify, options) {
  try {
    const zrp = new Odoo({
      baseUrl: options.baseUrl || 'http://portal.exatel.co.id',
      port: options.port || 8069,
      db: options.db || 'zeniverse',
      username: 'exa',
      password: 'exa',
    });

    await zrp.connect();
    fastify.decorate('zrp', zrp);
    fastify.log.info(`ZRP client is initialized:\n${JSON.stringify(zrp, null, 2)}`);

    // Create a 'contactus' endpoint
    fastify.post('/contactus', async (request, reply) => {
      const { name, email, company_name, mobile, services, message } = request.body;

      if (!name || !email || !message || !services) {
        return reply.status(400).send({ error: 'Name, email, services, and message are required' });
      }

      try {
        const leadId = await zrp.create('crm.lead', {
          name: `exatel.co.id - Contact from ${name}`,
          contact_name: name,
          email_from: email,
          partner_name: company_name,
          mobile: mobile,
          description: `${services}\n${message}`,
          type: 'lead',
        });

        fastify.log.info(`Contact form submitted successfully: ${leadId}`);
        return reply.send({ message: 'Contact form submitted successfully', leadId });
      } catch (error) {
        fastify.log.error('Failed to submit contact form:', error);
        return reply.status(500).send({ error: 'Failed to submit contact form' });
      }
    });

    // Run the test after the plugin is fully initialized
    fastify.after(async () => {
      try {
        await testLeadCreationAndDeletion(fastify);
      } catch (error) {
        fastify.log.error(`Test failed: ${error.message}`);
      }
    });

  } catch (error) {
    fastify.log.error('Failed to initialize ZRP client:', error);
    throw new Error('ZRP client initialization failed');
  }
}

// Function to create a lead
async function createLead(fastify, leadData) {
  try {
    const response = await fastify.inject({
      method: 'POST',
      url: '/contactus',
      payload: leadData,
    });

    const responseData = JSON.parse(response.payload);
    if (response.statusCode === 200) {
      fastify.log.info(`Lead created successfully with ID: ${responseData.leadId}`);
      return responseData.leadId;
    } else {
      throw new Error(`Failed to create lead: ${responseData.error}`);
    }
  } catch (error) {
    throw new Error(`Error creating lead: ${error.message}`);
  }
}

// Function to delete a lead
async function deleteLead(fastify, leadId) {
  try {
    await fastify.zrp.delete('crm.lead', [leadId]);
    fastify.log.info(`Lead with ID ${leadId} deleted successfully`);
  } catch (error) {
    throw new Error(`Error deleting lead: ${error.message}`);
  }
}

// Function that runs the create and delete test
async function testLeadCreationAndDeletion(fastify) {
  fastify.log.info('Running lead creation and deletion test...');

  const leadData = {
    name: 'John Doe',
