odoo.define('zeniverse_gis.location_picker', function (require) {
    'use strict';

    const FormView = require('web.FormView');
    const core = require('web.core');
    const Dialog = require('web.Dialog');
    const QWeb = require('web.QWeb');

    FormView.include({
        render_form: function (arch, options) {
            this._super(arch, options);
            const self = this;

            this.$('.o_field_widget[name="partner_latitude"], .o_field_widget[name="partner_longitude"]').each(function () {
                const $latField = self.$('.o_field_widget[name="partner_latitude"]');
                const $longField = self.$('.o_field_widget[name="partner_longitude"]');

                const $button = $('<button type="button" class="btn btn-primary">Pick Location</button>');
