import { getGenerativeModel, generationConfig } from './config.js';
import { showMainMenu } from '../aiPlugins/mainMenu.js';
import { execute_command } from '../aiPlugins/bashShell.js';
import { odoo_crud_operations } from '../aiPlugins/odooCrudOperations.js';
import { subscriber_information } from '../aiPlugins/fetchSubscriber.js';
import { createPSB } from '../aiPlugins/createPSB.js';
import { search_or_scrape } from '../aiPlugins/googleSearch.js';
import { autonomous_project_management } from '../aiPlugins/autonomous_project_management.js';

export default async function googleGenerativeAIPlugin(fastify, options) {
    const chatHistories = new Map();

    const functionHandlers = {
        execute_command,
        fetch_subscriber_info: subscriber_information,
        create_psb: createPSB,
        odoo_crud_operations,
        search_or_scrape,
        autonomous_project_management,
    };

    fastify.decorate('chat', async (inputText, agentName) => {
        const model = await getGenerativeModel(agentName);
        if (!model) throw new Error('Generative model not found');

        const history = chatHistories.get(agentName) || [];
        const chatSession = model.startChat({ generationConfig, history });

        let response = await chatSession.sendMessage(inputText);
        let functionCalls = response.response.functionCalls() || [];

        while (functionCalls.length > 0) {
            const apiResponses = await Promise.all(
                functionCalls.map(async (call) => {
                    const handler = functionHandlers[call.name];
                    const responseContent = handler
                        ? JSON.stringify(await handler(call.args))
                        : `Function '${call.name}' is not implemented`;
                    return { name: call.name, response: { content: responseContent } };
                })
            );

            const functionResponses = apiResponses.map(({ name, response }) => ({
                functionResponse: { name, response },
            }));

            response = await chatSession.sendMessage(functionResponses);
            functionCalls = response.response.functionCalls() || [];
        }

        const responseText = response.response.text();
        history.push({ role: "user", parts: [{ text: inputText }] });
        history.push({ role: "model", parts: [{ text: responseText }] });

        chatHistories.set(agentName, history);

        return responseText;
    });

    fastify.post('/chat', async (request, reply) => {
        const { text, agent } = request.body;
        if (!text) return reply.status(400).send({ error: 'Text input is required' });

        try {
            const content = await fastify.chat(text, agent);
            return reply.send({ text: content });
        } catch (error) {
            console.error('Error during content generation:', error);
            return reply.status(500).send({ error: 'Failed to generate content' });
        }
    });
}



