To make your routing script interactive and display the routing table, we can use the `readline` module for user input and modify your script accordingly. Here’s how you can implement this:

### Updated Script (app.js)

```javascript
const { exec } = require('child_process');
const readline = require('readline');

const route = '10.0.0.0/24';
const gateway = '160.22.193.34';

// Create an interface for input and output
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

// Function to add the route
function addRoute() {
    exec(`ip route add ${route} via ${gateway}`, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error adding route: ${error.message}`);
            return;
        }
        if (stderr) {
            console.error(`stderr: ${stderr}`);
            return;
        }
        console.log(`Route added: ${route} via ${gateway}`);
    });
}

// Function to remove the route
function removeRoute() {
    exec(`ip route del ${route} via ${gateway}`, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error removing route: ${error.message}`);
            return;
        }
        if (stderr) {
            console.error(`stderr: ${stderr}`);
            return;
        }
        console.log(`Route removed: ${route} via ${gateway}`);
    });
}

// Function to show the routing table
function showRoutingTable() {
    exec('ip route show', (error, stdout, stderr) => {
        if (error) {
            console.error(`Error showing routing table: ${error.message}`);
            return;
        }
        if (stderr) {
            console.error(`stderr: ${stderr}`);
            return;
        }
        console.log(`Current Routing Table:\n${stdout}`);
    });
}

// Function to handle user input
function startInteractiveMode() {
    console.log('Routing Management');
    console.log('1. Show Routing Table');
    console.log('2. Add Route');
    console.log('3. Remove Route');
    console.log('4. Exit');

    rl.on('line', (input) => {
        switch (input.trim()) {
            case '1':
                showRoutingTable();
                break;
            case '2':
                addRoute();
                break;
            case '3':
                removeRoute();
                break;
            case '4':
                console.log('Exiting...');
                removeRoute(); // Clean up before exiting
                rl.close();
                break;
            default:
                console.log('Invalid option. Please choose again.');
        }
    });
}

// Add the route when the script starts
addRoute();

// Show the interactive menu
startInteractiveMode();

// Remove the route on exit
process.on('SIGINT', () => {
    console.log('Stopping script...');
    removeRoute();
    rl.close();
    process.exit();
});

process.on('SIGTERM', () => {
    console.log('Stopping script...');
    removeRoute();
    rl.close();
    process.exit();
});
```

### Explanation of Changes

1. **Interactive Input**: 
   - The `readline` module is used to handle user inputs interactively.
   - The user can choose to show the routing table, add a route, remove a route, or exit the application.

2. **Show Routing Table**:
   - The `showRoutingTable` function executes the command to display the current routing table.

3. **Menu System**:
   - A simple menu is displayed to the user, providing options for various actions.

4. **Graceful Exit**:
   - The route is removed when exiting the program either through the menu or by using `Ctrl + C`.

### How to Run

1. Save the script to `app.js`.
2. Open a terminal and navigate to the directory where `app.js` is located.
3. Run the script using Node.js:
   ```bash
