fastify.post('/check-in', async (request, reply) => {
  const { username, password, image, latitude, longitude } = request.body;

  if (!username || !password) {
    return reply.status(400).send({ error: 'Username, password, employee ID, and timestamp are required' });
  }

  try {
    const dynamicClient = await fastify.dynamicOdooClient(username, password);

    // Retrieve the user's employee and partner information
    const user = await dynamicClient.read('res.users', [dynamicClient.uid], ['employee_id', 'partner_id']);
    const employee_id = user[0]?.employee_id;
    const partner_id = user[0]?.partner_id;

    if (!employee_id || !partner_id) {
      return reply.status(404).send({ error: 'Employee or Partner ID not found' });
