        const taskRecords = await dynamicClient.searchRead('project.task', [['user_ids', 'in', dynamicClient.uid]], ['name','project_id','create_uid', 'date_deadline', 'stage_id']);

        return reply.send({ code: 200, message: 'Task records retrieved successfully', data: taskRecords });
      } catch (error) {
        fastify.log.error(`Failed to retrieve task records: ${error.message}`);
        return reply.status(500).send({ error: `'Failed to retrieve task records'` });
      }
    });

    // Endpoint untuk detail tugas berdasarkan ID (dikirim melalui body)
    fastify.post('/task', async (request, reply) => {
      const { username, password, id } = request.body;

      if (!username || !password || !id) {
        return reply.status(400).send({ error: 'Username, password, and id are required' });
      }

      try {
        const dynamicClient = await fastify.dynamicOdooClient(username, password);

        // Retrieve the specific task detail using the id from the body
        const taskDetail = await dynamicClient.read('project.task', [parseInt(id)], ['name', 'project_id', 'user_ids', 'stage_id', 'date_deadline', 'description', 'priority', 'create_uid']);

        if (taskDetail.length === 0) {
          return reply.status(404).send({ error: 'Task not found' });
        }

        return reply.send({ code: 200, message: 'Task detail retrieved successfully', data: taskDetail[0] });
      } catch (error) {
        fastify.log.error(`Failed to retrieve task detail: ${error.message}`);
        return reply.status(500).send({ error: `'Failed to retrieve task detail'` });
      }
    });

  } catch (error) {
    fastify.log.error('Failed to initialize Odoo client:', error);
    throw new Error('Odoo client initialization failed');
  }
}

