```javascript
import Odoo from 'odoo-await';
import { convertToGMT7 } from '../../../../utils/timeUtils.js';

async function zrpPlugin(fastify, options) {
  try {
    // Decorator for dynamic Odoo client
    fastify.decorate('dynamicOdooClient', async (username, password) => {
      if (!username || !password) {
        throw new Error('Username and password are required for dynamic Odoo client.');
      }

      const dynamicClient = new Odoo({
        baseUrl: options.baseUrl || 'http://portal.exatel.co.id',
        port: options.port || 8069,
        db: options.db || 'portal.exatel.co.id',
        username,
        password,
      });

      await dynamicClient.connect();
      return dynamicClient;
    });

    // Endpoint to retrieve subscriber by subscriber_code
    fastify.get('/subscriber', async (request, reply) => {
      const { username, password, subscriber_code } = request.query;

      if (!username || !password || !subscriber_code) {
        return reply.status(400).send({ error: 'Username, password, and subscriber_code are required' });
      }

      try {
        const dynamicClient = await fastify.dynamicOdooClient(username, password);

        // Search for orders with the specified subscriber_code
        const subscriberRecords = await dynamicClient.searchRead(
          'sale.order',
          [['subscriber_code', '=', subscriber_code]],
          ['name', 'partner_id', 'date_order', 'amount_total']
        );

        // Convert date_order to GMT+7 if available
        const adjustedSubscriberRecords = subscriberRecords.map(order => ({
          ...order,
          date_order: order.date_order ? convertToGMT7(order.date_order) : null
        }));

        return reply.send({ code: 200, message: 'Subscriber records retrieved successfully', data: adjustedSubscriberRecords });
      } catch (error) {
        fastify.log.error(`Failed to retrieve subscriber records: ${error.message}`);
        return reply.status(500).send({ error: 'Failed to retrieve subscriber records' });
      }
    });

    // Other existing endpoints go here...

  } catch (error) {
    fastify.log.error('Failed to initialize Odoo client:', error);
    throw new Error('Odoo client initialization failed');
  }
}

// Export the plugin for use in the main application
export default zrpPlugin;
