```css
:root {
  --base-font-size: 13px;
  --base-line-height: 16px;

  /* Warna untuk Dark Mode */
  --color1: #2e2e2e; /* Border dan elemen latar */
  --color2: #4b4b4b; /* Latar komponen */
  --color3: #1f1f1f; /* Latar utama */
  --color4: #6db3f2; /* Warna utama, seperti link dan outline */
  --color5: #eaeaea; /* Teks */

  --fade: 0.2s;

  --disabled: #666;

  --status-red: 0 60% 50%; /* Warna status merah */
  --status-green: 120 60% 50%; /* Warna status hijau */
  --status-gray: 58 10% 50%; /* Warna status abu-abu */
  --status-yellow: 46 60% 50%; /* Warna status kuning */
}

