import os
import importlib
import inspect
import time
import logging
import asyncio
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor
from fastapi import APIRouter, HTTPException, Depends
from fastapi.responses import PlainTextResponse
import aiofiles
from app.llm.gemini import GeminiClient

router = APIRouter()
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
CACHE_FILE = "cached_home.md"
CACHE_EXPIRATION = 24 * 60 * 60
MAX_ITERATIONS = 5
EXECUTOR = ThreadPoolExecutor(max_workers=4)

async def is_cache_valid():
    if not os.path.exists(CACHE_FILE):
        return False
    return (time.time() - os.path.getmtime(CACHE_FILE)) < CACHE_EXPIRATION

async def save_to_cache(content):
    async with aiofiles.open(CACHE_FILE, "w", encoding="utf-8") as f:
        await f.write(content)

async def load_from_cache():
    async with aiofiles.open(CACHE_FILE, "r", encoding="utf-8") as f:
        return await f.read()

async def analyze_files(folder):
    loop = asyncio.get_event_loop()
    results = []
    for root, dirs, files in os.walk(folder):
        dirs[:] = [d for d in dirs if not (d.startswith(".") or d.startswith("__") or d == "node_modules")]
        for file in files:
            if file.endswith(".py") and file != "__init__.py":
                path = os.path.join(root, file)
                rel_path = os.path.relpath(path, folder)
                module_name = rel_path.replace(os.sep, ".")[:-3]
                info = {"filename": rel_path, "properties": []}
                try:
                    mod = await loop.run_in_executor(EXECUTOR, importlib.import_module, module_name)
                    for name, obj in inspect.getmembers(mod):
                        if not name.startswith("__"):
                            info["properties"].append({
                                "name": name,
                                "type": str(type(obj)),
                                "doc": inspect.getdoc(obj) or ""
                            })
                except Exception as e:
                    info["error"] = str(e)
                results.append(info)
    return results

async def refine_content(client, base_prompt, initial_content, revision_instruction, task):
    content = initial_content
    iteration = 0
    while iteration < MAX_ITERATIONS:
        iteration += 1
        prompt = f"{revision_instruction}\n\nPrevious result:\n{content}\n\nImprove the content."
        try:
            revised = client.generate_content(prompt=prompt)
        except Exception as e:
            break
        response = client.generate_content(
            prompt=f"Evaluate if the content for task '{task}' is complete and high-quality. Answer 'yes' if revision is needed, otherwise 'no'. Content:\n{revised}"
        ).lower()
        if "no" in response:
            return revised
        content = revised
    return content

class PlannerAgent:
    def __init__(self, client):
        self.client = client
    def generate_analysis(self, files):
        prompt = f"Analyze these Python files and generate a Markdown summary with file descriptions, key functionalities, and notable implementation details:\n{files}"
        return self.client.generate_content(prompt=prompt)

class ReflectionAgent:
    def __init__(self, client):
        self.client = client
    def evaluate_revision(self, content, task):
        prompt = f"Determine if the content for task '{task}' needs further revision. Answer 'yes' or 'no'.\nContent:\n{content}"
        response = self.client.generate_content(prompt=prompt).lower()
        return "yes" in response

class MemoryAgent:
    def __init__(self):
        self.history = {}
    def record(self, key, value):
        self.history[key] = value
    def retrieve(self, key):
        return self.history.get(key, None)

class CrewAgent:
    def __init__(self, client):
        self.client = client
    def generate_structure(self, analysis):
        prompt = f"Create a clean, semantic Markdown document structure with sections: Overview, Analyzed Files, and Key Features based on the following analysis:\n{analysis}"
        return self.client.generate_content(prompt=prompt)
    def enhance_design(self, structure):
        prompt = f"Enhance the following Markdown for readability and organization with proper headings, lists, and code blocks:\n{structure}"
        return self.client.generate_content(prompt=prompt)
    def add_knowledge_base(self, design):
        prompt = f"Extend the Markdown document by adding a dedicated knowledge base section with a table of contents and navigation links:\n{design}"
        return self.client.generate_content(prompt=prompt)

class Manager:
    def __init__(self, client):
        self.client = client
        self.planner = PlannerAgent(client)
        self.reflection = ReflectionAgent(client)
        self.crew = CrewAgent(client)
        self.memory = MemoryAgent()
    async def orchestrate(self, folder):
        files = await analyze_files(folder)
        initial_analysis = self.planner.generate_analysis(files)
        analysis = await refine_content(
            self.client, "", initial_analysis,
            "Refine the analysis to include detailed project structure and file functionalities in Markdown.",
            "Analysis"
        )
        self.memory.record("analysis", analysis)
        structure_initial = self.crew.generate_structure(analysis)
        structure = await refine_content(
            self.client, "", structure_initial,
            "Refine the structure with proper headings, lists, and clear sections.",
            "Structure"
        )
        design_initial = self.crew.enhance_design(structure)
        design = await refine_content(
            self.client, "", design_initial,
            "Refine the design for consistent formatting and improved clarity.",
            "Design"
        )
        kb_initial = self.crew.add_knowledge_base(design)
        kb = await refine_content(
            self.client, "", kb_initial,
            "Refine the knowledge base section ensuring a clear table of contents and navigation links.",
            "Knowledge Base"
        )
        release_date = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        optimization_prompt = f"Optimize the following Markdown by adding a release date at the top in the format 'Generated on: {release_date}' and ensuring overall readability:\n{kb}"
        optimized_initial = self.client.generate_content(prompt=optimization_prompt)
        optimized = await refine_content(
            self.client, "", optimized_initial,
            "Ensure the release date is clearly at the top and formatting is clean.",
            "Optimization"
        )
        final_doc = f"Generated on: {release_date}\n\n{optimized.replace('```','')}"
        self.memory.record("final_doc", final_doc)
        return final_doc

def get_gemini_client():
    api_key = os.getenv("GEMINI_API_KEY")
    if not api_key:
        raise HTTPException(status_code=500, detail="GEMINI_API_KEY not set")
    return GeminiClient(api_key=api_key)

@router.get("/", response_class=PlainTextResponse)
async def read_root(client: GeminiClient = Depends(get_gemini_client)):
    if await is_cache_valid():
        return PlainTextResponse(content=await load_from_cache(), media_type="text/markdown")
    folder = os.path.join(os.path.dirname(__file__), "..", "..")
    manager = Manager(client)
    final_markdown = await manager.orchestrate(folder)
    await save_to_cache(final_markdown)
    return PlainTextResponse(content=final_markdown, media_type="text/markdown")
```

