If you prefer not to use a library and want to create the text scramble effect yourself, you can implement it using JavaScript and CSS. Here's how you can create a simple scramble effect from scratch:

### Step 1: Create the Scramble Text Effect

You can achieve the text scramble effect using `setInterval()` to progressively replace each character in the text with a random character, simulating the "scramble" effect.

#### Example: ScrambleText Component (No External Library)

```tsx
'use client'

import { useEffect, useRef, useState } from 'react';

const ScrambleText = ({ text }: { text: string }) => {
  const [scrambledText, setScrambledText] = useState('');
  const textRef = useRef(text);
  const scrambleInterval = useRef<NodeJS.Timeout | null>(null);

  // Generate random characters for scrambling
  const getRandomChar = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    return chars.charAt(Math.floor(Math.random() * chars.length));
  };

  useEffect(() => {
    const scramble = () => {
      let currentScrambledText = '';
      let textLength = text.length;

      for (let i = 0; i < textLength; i++) {
        currentScrambledText += getRandomChar();
      }

      setScrambledText(currentScrambledText);
    };

    // Start the scrambling process every 50ms
    scrambleInterval.current = setInterval(() => {
      scramble();
    }, 50);

    // Stop scrambling once the target text is reached
    setTimeout(() => {
      clearInterval(scrambleInterval.current!);
      setScrambledText(text); // Set to the original text
    }, 2000); // Scramble effect lasts for 2 seconds

    return () => {
      if (scrambleInterval.current) clearInterval(scrambleInterval.current);
    };
  }, [text]);

  return (
    <span className="text-primary font-bold">
      {scrambledText}
    </span>
  );
};

export default ScrambleText;
```

