const prisma = new PrismaClient()

/**
 * Fetch user data, glocally, with support for locale-based customization.
 * @param {string} locale - The locale for the request (default to 'en-US').
 * @param {Object} filters - Optional filters to apply to the query.
 * @returns {Promise<Array>} - List of users with related data.
 */
export const getUserData = async (locale = 'en-US', filters = {}) => {
  try {
    console.log(`Fetching user data for locale: ${locale}`)

