const start = async () => {
  const fastify = await buildServer(); // Panggil async untuk membangun server

  try {
    // Panggil listen setelah plugin terdaftar
    await fastify.listen({ port: 4000, host: '0.0.0.0' });
    fastify.log.info(`Server is running...`);
  } catch (err) {
    // Pastikan fastify.log sudah terpasang dengan benar
    if (fastify.log) {
      fastify.log.error(`Error starting server: ${err.message}`);
    } else {
      console.error('Error starting server:', err);
    }
    process.exit(1);
  }
};

start();
```

#### 2. Pastikan Logger pada `buildServer()`:
Pada `buildServer()`, jika kamu menggunakan logger eksternal atau custom logger, pastikan itu sudah disiapkan dengan benar.

```javascript
import Fastify from 'fastify';
import cuid from 'cuid';
import { registerPlugins } from './Loader.js';  // Import plugin registration

// Function to build the Fastify server
const buildServer = async (logger = null) => {
  const fastify = Fastify({
    genReqId: () => cuid(),
    logger: logger || true,  // Use Fastify's default logger if no logger is passed
  });

  await registerPlugins(fastify);  // Register the plugins

  fastify.get('/', async (request, reply) => {
    fastify.log.info('Hello endpoint accessed');
    return { hello: 'world' };
  });

  return fastify;
};

export default buildServer;
```

### Penjelasan:
1. **Logger Default Fastify**:
   Jika kamu tidak mengirim logger eksternal (seperti pino atau custom logger), Fastify sudah menyediakan logger default yang akan menangani log, termasuk error.

2. **Periksa jika `fastify.log` ada**:
   Pastikan sebelum menggunakan `fastify.log.error()`, kamu memeriksa apakah `fastify.log` benar-benar ada. Ini mencegah error ketika logger tidak terpasang.

