```javascript
import jwt from '@fastify/jwt';

async function fp(fastify, opts) {
    const secret = '210491210491210491';  // Secret key to sign the JWT token

    // Register the JWT plugin
    fastify.register(jwt, { secret });

    // Example route to sign and generate a JWT token
    fastify.post('/login', async (request, reply) => {
        const { username, password } = request.body;

        // Logic to authenticate user (example, could be checking against a database)
        if (username === 'bjo163@gmail.com' && password === 'Youknowm@2025') {
            // User authenticated, generate JWT token
            const payload = {
