            };

            const token = fastify.jwt.sign(payload, { expiresIn: '1h' });

            return { message: 'Login successful', token };
        } else {
            return reply.status(401).send({ error: 'Invalid credentials' });
        }
    });

    // Example route to verify the JWT token (protected route)
    fastify.get('/protected', { preHandler: fastify.auth([fastify.verifyJWT]) }, async (request, reply) => {
        return { message: 'This is a protected route', user: request.user };
    });

    // JWT verification middleware
    fastify.decorate('verifyJWT', async (request, reply) => {
        try {
            // Extract token from Authorization header
            const token = request.headers['authorization']?.split(' ')[1];

            if (!token) {
                return reply.status(401).send({ error: 'Token not provided' });
            }

            // Verify the token using the JWT plugin
            const decoded = await fastify.jwt.verify(token);
            request.user = decoded; // Attach decoded user info to request object
        } catch (error) {
            return reply.status(401).send({ error: 'Invalid or expired token' });
        }
    });
}

export default fp;
```

