```javascript
fastify.get('/api/be', async (request, reply) => {
  const verify = await request.jwtVerify();
  const { username, password } = verify;

  // Ambil parameter model dari querystring
  const { model } = request.query;

  if (!model) {
    return reply.status(400).send({
      statusCode: 400,
      error: 'Bad Request',
      message: 'Model parameter is required',
    });
  }

  try {
    const con = await fastify.auth(username, password);
    const res = await con.searchRead(model); // <-- pakai param model
    reply.send(res);
  } catch (error) {
    request.log.error(error);
    return reply.status(500).send({
      statusCode: 500,
      error: 'Internal Server Error',
      message: error.message || 'Unknown error occurred',
    });
  }
});
```

