          total: res.length,
          per_page: res.length,
          current_page: 1,
          last_page: 1,
          offset: 0,
          limit: res.length,
          from: 1,
          to: res.length,
          has_next: false,
          has_prev: false,
        },
        links: {
          first: null,
          prev: null,
          next: null,
          last: null,
        }
      });
    }

    // ❗ Ada offset/limit ➔ baru paging
    const paginatedData = res.slice(offset, offset + limit);

    const meta = {
      total: res.length,
      per_page: limit,
      current_page: Math.floor(offset / limit) + 1,
      last_page: Math.ceil(res.length / limit),
      offset: offset,
      limit: limit,
      from: offset + 1,
      to: offset + paginatedData.length,
      has_next: offset + limit < res.length,
      has_prev: offset > 0,
    };

    const baseUrl = `${request.protocol}://${request.headers.host}${request.raw.url.split('?')[0]}`;

    const links = {
      first: `${baseUrl}?offset=0&limit=${limit}`,
      prev: meta.has_prev ? `${baseUrl}?offset=${Math.max(offset - limit, 0)}&limit=${limit}` : null,
      next: meta.has_next ? `${baseUrl}?offset=${offset + limit}&limit=${limit}` : null,
      last: `${baseUrl}?offset=${(meta.last_page - 1) * limit}&limit=${limit}`,
    };

    return reply.send({
      data: paginatedData,
      meta,
      links,
    });

