### ✅ `formatResponse.js` fix:

```javascript
export function formatResponse(data = [], options = {}) {
  const {
    total = data.length, // fallback kalau tidak dikasih
    limit = total,
    offset = 0,
  } = options;

  const perPage = parseInt(limit);
  const currentPage = perPage ? Math.floor(offset / perPage) + 1 : 1;
  const lastPage = perPage ? Math.ceil(total / perPage) : 1;

  return {
    data,
    meta: {
      total,
      per_page: perPage,
      current_page: currentPage,
      last_page: lastPage,
    },
  };
}
```

