export function formatResponse(data = [], options = {}) {
  const {
    total = data.length,
    limit = total,
    offset = 0,
    baseUrl = '', // contoh: http://127.0.0.1:4000/api/be
    query = {},   // query tambahan misal { model: 'res.partner' }
  } = options;

  const perPage = parseInt(limit);
  const totalRecords = parseInt(total);
  const currentPage = perPage ? Math.floor(offset / perPage) + 1 : 1;
  const totalPages = perPage ? Math.ceil(totalRecords / perPage) : 1;

  const from = totalRecords === 0 ? 0 : offset + 1;
  const to = Math.min(offset + perPage, totalRecords);

  const hasNext = currentPage < totalPages;
  const hasPrev = currentPage > 1;

  // Helper untuk build query string
  const buildQuery = (params) => {
    const search = new URLSearchParams({ ...query, ...params });
    return `${baseUrl}?${search.toString()}`;
  };

  const links = {
    first: buildQuery({ offset: 0, limit: perPage }),
    prev: hasPrev ? buildQuery({ offset: Math.max(offset - perPage, 0), limit: perPage }) : null,
    next: hasNext ? buildQuery({ offset: offset + perPage, limit: perPage }) : null,
    last: buildQuery({ offset: (totalPages - 1) * perPage, limit: perPage }),
  };

  return {
    data,
    meta: {
      total_records: totalRecords,
      total_pages: totalPages,
      current_page: currentPage,
      per_page: perPage,
      offset,
      limit: perPage,
      from,
      to,
      has_next: hasNext,
      has_prev: hasPrev,
    },
    links,
  };
}
```

