import crypto from 'crypto';

/**
 * =====================================================
 * VERIFY PASSWORD
 * Support:
 * - PAP
 * - CHAP
 * - MS-CHAP v1 / v2
 * Password disimpan CLEAR TEXT di database
 * =====================================================
 */
const verifyPassword = (packet, storedPassword) => {
  /**
   * =========================
   * 1️⃣ PAP (User-Password)
   * =========================
   */
  if (packet.attributes['User-Password']) {
    const received = packet.attributes['User-Password']
      .toString()
      .replace(/\0/g, '')
      .trim();

    return received === storedPassword;
  }

  /**
   * =========================
   * 2️⃣ CHAP
   * =========================
   */
  if (packet.attributes['CHAP-Password']) {
    const chapBuf = packet.attributes['CHAP-Password'];
    if (chapBuf.length < 17) return false;

    const chapId = chapBuf[0];
    const chapHash = chapBuf.slice(1, 17);
    const challenge =
      packet.attributes['CHAP-Challenge'] || packet.authenticator;

    const expectedHash = crypto
      .createHash('md5')
      .update(
        Buffer.concat([
          Buffer.from([chapId]),
          Buffer.from(storedPassword),
          challenge,
        ])
      )
      .digest();

    return Buffer.compare(chapHash, expectedHash) === 0;
  }

  /**
   * =========================
   * 3️⃣ MS-CHAP v1 / v2
   * =========================
   */
  if (packet.attributes['MS-CHAP-Challenge']) {
    const challenge = packet.attributes['MS-CHAP-Challenge'];

    const response =
      packet.attributes['MS-CHAP-Response'] ||
      packet.attributes['MS-CHAP2-Response'];

    if (!response) return false;

    try {
      return radius.mschap.verify({
        challenge,
        response,
        password: storedPassword,
      });
    } catch (err) {
      return false;
    }
  }

  return false;
};

/**
 * =====================================================
 * HANDLE AUTH REQUEST
 * =====================================================
 */
export const handleAuth = async (
  packet,
  rinfo,
  socket,
  secret,
  env,
  server,
  config
) => {
  const username = packet.attributes['User-Name'];
  const SecretModel = env['zms.secret'];

  let code = 'Access-Reject';
  let response_attrs = [];

  try {
    /**
     * =========================
     * 1️⃣ Cari user di database
     * =========================
     */
    const dbRecord = await SecretModel.query()
      .where('username', username)
      .where('active', true)
      .first();

    if (!dbRecord) {
      server.log.warn(`[RADIUS] ❓ NOT FOUND: ${username}`);
      response_attrs.push(['Reply-Message', 'User Unknown']);
      throw new Error('USER_NOT_FOUND');
    }

    /**
     * =========================
     * 2️⃣ Cek expired
     * =========================
     */
    if (
      dbRecord.expiration_date &&
      new Date(dbRecord.expiration_date) < new Date()
    ) {
      server.log.warn(`[RADIUS] ⛔ EXPIRED: ${username}`);
      response_attrs.push(['Reply-Message', 'Account Expired']);
      throw new Error('ACCOUNT_EXPIRED');
    }

    /**
     * =========================
     * 3️⃣ Verifikasi password
     * =========================
     */
    const isValid = verifyPassword(packet, dbRecord.password);

    if (!isValid) {
      server.log.warn(`[RADIUS] ❌ WRONG PASS: ${username}`);
      response_attrs.push(['Reply-Message', 'Invalid Password']);
      throw new Error('INVALID_PASSWORD');
    }

    /**
     * =========================
     * 4️⃣ ACCEPT
     * =========================
     */
    code = 'Access-Accept';
    server.log.info(`[RADIUS] ✅ ACCEPTED: ${username}`);

    // Mikrotik Rate Limit (optional)
    if (dbRecord.limit_info) {
      response_attrs.push([
        'Vendor-Specific',
        'Mikrotik',
        [['Mikrotik-Rate-Limit', dbRecord.limit_info]],
      ]);
    }

    response_attrs.push([
      'Reply-Message',
      `Hi ${dbRecord.name || username}, XSP Connected`,
    ]);
  } catch (err) {
    if (
      !['USER_NOT_FOUND', 'ACCOUNT_EXPIRED', 'INVALID_PASSWORD'].includes(
        err.message
      )
    ) {
      server.log.error(`[RADIUS-ERROR] ${err.message}`);
    }
  }

  /**
   * =========================
   * 5️⃣ Kirim response
   * =========================
   */
  try {
    const response = radius.encode({
      code,
      secret,
      attributes: response_attrs,
      identifier: packet.identifier,
      authenticator: packet.authenticator,
    });

    socket.send(response, 0, response.length, rinfo.port, rinfo.address);
  } catch (err) {
    server.log.error(`[RADIUS-ENCODE-FATAL] ${err.message}`);
  }
};

