import radius from 'radius';
import crypto from 'crypto';

export const verifyPassword = (packet, storedPassword, server) => {
  const attrs = packet.attributes;

  server.log.info('[RADIUS] Verify password started');

  /**
   * =========================
   * 1️⃣ PAP
   * =========================
   */
  if (attrs['User-Password']) {
    server.log.info('[RADIUS] Auth-Type: PAP');

    const received = attrs['User-Password']
      .toString('utf8')
      .replace(/\0/g, '')
      .trim();

    return received === String(storedPassword).trim();
  }

  /**
   * =========================
   * 2️⃣ CHAP
   * =========================
   */
  if (attrs['CHAP-Password']) {
    server.log.info('[RADIUS] Auth-Type: CHAP');

    const chapBuf = attrs['CHAP-Password'];
    const chapId = chapBuf[0];
    const chapHash = chapBuf.slice(1);
    const challenge = attrs['CHAP-Challenge'] || packet.authenticator;

    const expected = crypto
      .createHash('md5')
      .update(
        Buffer.concat([
          Buffer.from([chapId]),
          Buffer.from(storedPassword),
          challenge,
        ])
      )
      .digest();

    return Buffer.compare(chapHash, expected) === 0;
  }

  /**
   * =========================
   * 3️⃣ MS-CHAP v2 (PPPoE)
   * =========================
   */
  if (
    attrs['MS-CHAP-Challenge'] &&
    attrs['MS-CHAP2-Response']
  ) {
    server.log.info('[RADIUS] Auth-Type: MS-CHAPv2');

    try {
      return radius.mschap.verify({
        challenge: attrs['MS-CHAP-Challenge'],
        response: attrs['MS-CHAP2-Response'],
        password: storedPassword,
        username: attrs['User-Name'],
      });
    } catch (err) {
      server.log.info('[RADIUS] MS-CHAPv2 verify failed');
      return false;
    }
  }

  /**
   * =========================
   * UNKNOWN
   * =========================
   */
  server.log.info(
    `[RADIUS] Unknown auth type, attrs=${Object.keys(attrs).join(', ')}`
  );

  return false;
};
