      .createHash('md5')
      .update(
        Buffer.concat([
          Buffer.from([chapId]),
          Buffer.from(storedPassword),
          challenge,
        ])
      )
      .digest();

    return Buffer.compare(chapHash, expected) === 0;
  }

  // MS-CHAP v1 / v2
  if (
    packet.attributes['MS-CHAP-Response'] ||
    packet.attributes['MS-CHAP2-Response']
