      .update(
        Buffer.concat([
          Buffer.from([chapId]),
          Buffer.from(storedPassword),
          challenge,
        ])
      )
      .digest();

    const match =
      Buffer.compare(chap.slice(1), expected) === 0;

    server.log.info(
      `[RADIUS] CHAP verification ${match ? 'SUCCESS' : 'FAILED'}`
    );

    return match;
  }

  /**
   * =========================
   * 3️⃣ MS-CHAP v1 / v2
   * =========================
   */
  if (
    attrs['MS-CHAP-Response'] ||
    attrs['MS-CHAP2-Response']
  ) {
    const type = attrs['MS-CHAP2-Response']
      ? 'MS-CHAPv2'
      : 'MS-CHAPv1';

    server.log.info(`[RADIUS] Auth-Type: ${type}`);

    try {
      const result = radius.mschap.verify({
        packet,
        password: storedPassword,
        secret,
      });

      server.log.info(
        `[RADIUS] ${type} verification ${result ? 'SUCCESS' : 'FAILED'}`
      );

      return result;
    } catch (err) {
      server.log.info(`[RADIUS] ${type} verification error`);
      return false;
    }
  }

  server.log.info('[RADIUS] Unknown auth type');
  return false;
};

