    if (!dbRecord) {
      server.log.warn(`[RADIUS] ❓ USER NOT FOUND: ${username}`);
      response_attrs.push(['Reply-Message', 'User Unknown']);
      throw new Error('USER_NOT_FOUND');
    }

    /**
     * =========================
     * 3️⃣ EXPIRED CHECK
     * =========================
     */
    if (
      dbRecord.expiration_date &&
      new Date(dbRecord.expiration_date) < new Date()
    ) {
      server.log.warn(`[RADIUS] ⛔ EXPIRED: ${username}`);
      response_attrs.push(['Reply-Message', 'Account Expired']);
      throw new Error('ACCOUNT_EXPIRED');
    }

    /**
     * =========================
     * 4️⃣ PASSWORD VERIFY
     * =========================
     */
    const isValid = verifyPassword(packet, dbRecord.password, secret);

    if (!isValid) {
      server.log.warn(`[RADIUS] ❌ WRONG PASSWORD: ${username}`);
      response_attrs.push(['Reply-Message', 'Invalid Password']);
      throw new Error('INVALID_PASSWORD');
    }

    /**
     * =========================
     * 5️⃣ ACCESS-ACCEPT
     * =========================
     */
    code = 'Access-Accept';
    server.log.info(`[RADIUS] ✅ ACCEPTED: ${username}`);

    /**
     * =========================
     * 6️⃣ MIKROTIK ATTR (OPTIONAL)
     * =========================
     */
    if (dbRecord.limit_info) {
      response_attrs.push([
        'Vendor-Specific',
        'Mikrotik',
        [['Mikrotik-Rate-Limit', dbRecord.limit_info]],
      ]);
    }

    response_attrs.push([
      'Reply-Message',
      `Hi ${dbRecord.name || username}, XSP Connected`,
    ]);
  } catch (err) {
    if (
      ![
        'NO_USERNAME',
        'USER_NOT_FOUND',
        'ACCOUNT_EXPIRED',
        'INVALID_PASSWORD',
      ].includes(err.message)
    ) {
      server.log.error(`[RADIUS-ERROR] ${err.message}`);
    }
  }

  /**
   * =========================
   * 7️⃣ SEND RESPONSE
   * =========================
   */
  try {
    const response = radius.encode({
      code,
      secret,
      identifier: packet.identifier,
      authenticator: packet.authenticator,
      attributes: response_attrs,
    });

    socket.send(response, 0, response.length, rinfo.port, rinfo.address);
  } catch (err) {
    server.log.error(`[RADIUS-ENCODE-FATAL] ${err.message}`);
  }
};
