## 📌 Script: `sync_radius.js`

```js
import { MikrotikClient } from 'rosinterface';
import pkg from 'pg';

const { Pool } = pkg;

async function main() {
  const client = new MikrotikClient({
    host: '101.255.109.198',
    user: 'admin',
    password: '210491',
    port: 48443,
    protocol: 'rest',
    rejectUnauthorized: false,
    rateLimit: 50,
    allowInsecureConfig: true,
  });

  const pool = new Pool({
    host: '160.22.193.46',
    port: 15432,
    user: 'postgres',
    password: 'mypassword',
    database: 'toughradius',
  });

  await client.connect();

  // ambil profile
  const profiles = await client.command('/ppp/profile')
    .select(['name', 'rate-limit'])
    .print();

  const profileMap = {};
  profiles._items.forEach(p => {
    profileMap[p.name] = p['rate-limit'];
  });

  // ambil secret
  const secrets = await client.command('/ppp/secret')
    .select(['name', 'service', 'profile', 'disabled', 'last-logged-out', 'password'])
    .print();

  // ambil active
  const active = await client.command('/ppp/active')
    .select(['name', 'caller-id', 'address'])
    .print();

  const activeMap = {};
  active._items.forEach(a => {
    activeMap[a.name] = {
      caller_id: a['caller-id'],
      address: a.address
    };
  });

  // gabungkan
  const result = secrets._items.map(s => ({
    username: s.name,
    service: s.service,
    profile: s.profile,
    disabled: s.disabled,
    last_logged_out: s['last-logged-out'],
    password: s.password || null,
    rate_limit: profileMap[s.profile] || null,
    active: activeMap[s.name] || null
  }));

  // proses ke PG
  for (const r of result) {
    const activeStatus = r.active ? 'active' : 'inactive';
    const ipAddr = r.active ? r.active.address : null;
    const lastOnline = r.active ? new Date() : null;
    const activeNum = r.active ? 1 : 0;

    // cek username sudah ada atau belum
    const { rows } = await pool.query(
      `SELECT id FROM radius_user WHERE username = $1`,
      [r.username]
    );

    if (rows.length > 0) {
      // update
      await pool.query(
        `UPDATE radius_user
         SET ip_addr = $1,
             last_online = $2,
             status = $3,
             active_num = $4,
             updated_at = NOW()
         WHERE username = $5`,
        [ipAddr, lastOnline, activeStatus, activeNum, r.username]
      );
    } else {
      // insert
      await pool.query(
        `INSERT INTO radius_user
          (username, password, profile_id, ip_addr, status, active_num, created_at, updated_at)
         VALUES ($1, $2, $3, $4, $5, $6, NOW(), NOW())`,
        [r.username, r.password, null, ipAddr, activeStatus, activeNum]
      );
    }
  }

  console.log('Sync selesai! total:', result.length);

  await client.close();
  await pool.end();
  process.exit(0);
}

main().catch(console.error);
```

