import { MikrotikClient } from 'rosinterface';
import pkg from 'pg';

const { Pool } = pkg;

async function main() {
  const client = new MikrotikClient({
    host: '101.255.109.198',
    user: 'admin',
    password: '210491',
    port: 48443,
    protocol: 'rest',
    rejectUnauthorized: false,
    rateLimit: 50,
    allowInsecureConfig: true,
  });

  const pool = new Pool({
    host: '160.22.193.46',
    port: 15432,
    user: 'postgres',
    password: 'mypassword',
    database: 'toughradius',
  });

  await client.connect();

  // ambil profile rate-limit
  const profiles = await client.command('/ppp/profile')
    .select(['name', 'rate-limit'])
    .print();

  const profileMap = {};
  profiles._items.forEach(p => {
    profileMap[p.name] = p['rate-limit'];
  });

  // ambil PPP secrets
  const secrets = await client.command('/ppp/secret')
    .select(['name', 'service', 'profile', 'disabled', 'last-logged-out', 'password'])
    .print();

  const result = secrets._items.map(s => ({
    username: s.name,
    password: s.password || null,
    profile: s.profile,
    service: s.service,
    disabled: s.disabled,
    last_logged_out: s['last-logged-out'],
    rate_limit: profileMap[s.profile] || null,
  }));

  // Expire 1 bulan dari sekarang
  const expireTime = new Date();
  expireTime.setMonth(expireTime.getMonth() + 1);
  const expireTimeStr = expireTime.toISOString().replace('T', ' ').split('.')[0];

  for (const r of result) {
    let up_rate = null;
    let down_rate = null;

    if (r.rate_limit) {
      const parts = r.rate_limit.split('/');
      down_rate = parts[0] ? convertToKbps(parts[0]) : null;
      up_rate = parts[1] ? convertToKbps(parts[1]) : null;
    }

    const remark = JSON.stringify({
      service: r.service,
      profile: r.profile,
      disabled: r.disabled,
      last_logged_out: r.last_logged_out,
      rate_limit: r.rate_limit
    });

    // UPSERT
    await pool.query(
      `INSERT INTO radius_user
        (username, password, up_rate, down_rate, active_num, status, remark, expire_time, updated_at)
       VALUES ($1, $2, $3, $4, 1, 'enabled', $5, $6, NOW())
       ON CONFLICT (username)
       DO UPDATE SET
         password = EXCLUDED.password,
         up_rate = EXCLUDED.up_rate,
         down_rate = EXCLUDED.down_rate,
         active_num = 1,
         status = 'enabled',
         remark = EXCLUDED.remark,
         expire_time = EXCLUDED.expire_time,
         updated_at = NOW();`,
      [r.username, r.password, up_rate, down_rate, remark, expireTimeStr]
    );

    console.log(`Upserted: ${r.username}`);
  }

  console.log('Sync upsert selesai!');

  await client.close();
  await pool.end();
  process.exit(0);
}

function convertToKbps(value) {
  const unit = value.slice(-1).toUpperCase();
  const num = parseFloat(value.slice(0, -1));

  if (unit === 'M') return num * 1024;
  if (unit === 'K') return num;
  if (unit === 'G') return num * 1024 * 1024;

  return parseFloat(value);
}

main().catch(console.error);
