```js
const MikroNode = require('mikronode');

const host = '192.168.88.1';
const user = 'admin';
const pass = 'password';

async function getSecrets() {
  try {
    const device = new MikroNode(host);
    const connection = await device.connect();

    // login
    await connection.login(user, pass);

    const chan = connection.openChannel();
    await chan.write('/ppp/secret/print');

    const data = await chan.read();
    console.log(data);

    // close connection
    connection.close();
  } catch (err) {
    console.error('Error:', err);
  }
}

getSecrets();
```

