use std::collections::HashMap;
use std::time::{Duration, Instant};

pub struct CacheItem {
    pub data: Vec<u8>,
    pub expire_at: Instant,
}

pub struct DnsCache {
    map: HashMap<String, CacheItem>,
}

impl DnsCache {
    pub fn new() -> Self {
        Self {
            map: HashMap::new(),
        }
    }

    pub fn set(&mut self, key: String, data: Vec<u8>, ttl: u32) {
        let expire_at = Instant::now() + Duration::from_secs(ttl as u64);
        self.map.insert(key, CacheItem { data, expire_at });
    }

    pub fn get(&mut self, key: &str) -> Option<Vec<u8>> {
        if let Some(item) = self.map.get(key) {
            if Instant::now() < item.expire_at {
                return Some(item.data.clone());
            }
        }
        self.map.remove(key);
        None
    }
}
