# ✅ Perbaikan kode cache (yang benar)

Berikut versi cache yang **benar**:

```rust
use trust_dns_proto::op::Message;
use std::collections::HashMap;
use std::time::{Instant, Duration};

struct CacheEntry {
    msg: Message,
    expire_at: Instant,
}

struct SimpleCache {
    map: HashMap<String, CacheEntry>,
    ttl: Duration,
}

impl SimpleCache {
    fn new(ttl_seconds: u64) -> Self {
        Self {
            map: HashMap::new(),
            ttl: Duration::from_secs(ttl_seconds),
        }
    }

    fn get(&self, key: &str) -> Option<Message> {
        if let Some(entry) = self.map.get(key) {
            if entry.expire_at > Instant::now() {
                return Some(entry.msg.clone());
            }
        }
        None
    }

    fn set(&mut self, key: &str, msg: Message) {
        self.map.insert(key.to_string(), CacheEntry {
            msg,
            expire_at: Instant::now() + self.ttl,
        });
    }
}
```

