use std::net::SocketAddr;
use tokio::net::UdpSocket;

use trust_dns_proto::op::{Message, MessageType, OpCode, Query};
use trust_dns_proto::rr::{Record, RData};
use trust_dns_proto::serialize::binary::*;
use trust_dns_proto::DnsHandle;

use trust_dns_client::client::AsyncClient;
use trust_dns_client::udp::UdpClientStream;
use trust_dns_client::proto::xfer::{DnsRequestOptions, DnsRequest};

async fn forward_query(query_bytes: &[u8], upstream: &str) -> Option<Vec<u8>> {
    let upstream_addr: SocketAddr = upstream.parse().unwrap();
    let stream = UdpClientStream::<UdpSocket>::new(upstream_addr);
    let (mut client, bg) = AsyncClient::connect(stream).await.ok()?;
    tokio::spawn(bg);

    let request_msg = Message::from_vec(query_bytes).ok()?;
    let request = DnsRequest::new(request_msg, Default::default());

    let response = client
        .send(request, DnsRequestOptions::default())
        .await
        .ok()?;

    let mut resp_buf = Vec::with_capacity(512);
    let mut encoder = BinEncoder::new(&mut resp_buf);
    response.emit(&mut encoder).ok()?;

    Some(resp_buf)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let addr: SocketAddr = "0.0.0.0:53".parse()?;
    let socket = UdpSocket::bind(addr).await?;
    println!("DNS server running on {}", addr);

    let mut buf = [0u8; 512];

    loop {
        let (len, src) = socket.recv_from(&mut buf).await?;
        let req = Message::from_vec(&buf[..len])?;
        let query = req.queries().first().unwrap();
        let name = query.name().to_string();

        println!("Query: {}", name);

        if name == "example.com." {
            let mut resp = Message::new();
            resp.set_id(req.id());
            resp.set_message_type(MessageType::Response);
            resp.set_op_code(OpCode::Query);
            resp.set_authoritative(true);
            resp.add_query(Query::query(query.name().clone(), query.query_type()));

            let record = Record::from_rdata(
                query.name().clone(),
                60,
                RData::A("1.2.3.4".parse().unwrap()),
            );

            resp.add_answer(record);

            let mut resp_buf = Vec::with_capacity(512);
            let mut encoder = BinEncoder::new(&mut resp_buf);
            resp.emit(&mut encoder)?;
            socket.send_to(&resp_buf, &src).await?;
            continue;
        }

        if let Some(resp) = forward_query(&buf[..len], "8.8.8.8:53").await {
            let _ = socket.send_to(&resp, &src).await;
            continue;
        }

        if let Some(resp) = forward_query(&buf[..len], "1.1.1.1:53").await {
            let _ = socket.send_to(&resp, &src).await;
            continue;
        }
    }
}
```

