use tokio::time::timeout;

use trust_dns_proto::op::{Message, MessageType, OpCode, Query};
use trust_dns_proto::rr::{Record, RData};
use trust_dns_proto::rr::rdata::A;
use trust_dns_proto::serialize::binary::*;

use once_cell::sync::Lazy;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let addr: SocketAddr = "0.0.0.0:53".parse()?;
    let socket = UdpSocket::bind(addr).await?;
    println!("DNS server running on {}", addr);

    let mut buf = [0u8; 512];

    loop {
        let (len, src) = socket.recv_from(&mut buf).await?;
        let req = Message::from_vec(&buf[..len])?;
        let query = req.queries().first().unwrap();
        let name = query.name().to_string();

        // rate limit per IP
        if !RATE_LIMIT.lock().unwrap().check(&src) {
            println!("Rate limit exceeded: {}", src);
            continue;
        }

        println!("Query: {}", name);

        // 1) Cache check
        if let Some(mut cached_msg) = CACHE.lock().unwrap().get(&name) {
            // Set ID sesuai request
            cached_msg.set_id(req.id());

            let mut resp_buf = Vec::with_capacity(512);
            let mut encoder = BinEncoder::new(&mut resp_buf);
            cached_msg.emit(&mut encoder).unwrap();

            let _ = socket.send_to(&resp_buf, &src).await;
            continue;
        }

        // 2) Hardcode domain tertentu
        if name == "example.com." {
            let resp = build_response(&req, query, "1.2.3.4".parse().unwrap());
            let _ = socket.send_to(&resp, &src).await;
            continue;
        }

        // 3) Forward ke upstream 8.8.8.8 (Google)
        if let Some(resp_msg) = forward_query(&buf[..len], "8.8.8.8:53").await {
            CACHE.lock().unwrap().set(&name, resp_msg.clone());

            let mut resp_buf = Vec::with_capacity(512);
            let mut encoder = BinEncoder::new(&mut resp_buf);
            resp_msg.emit(&mut encoder).unwrap();

            let _ = socket.send_to(&resp_buf, &src).await;
            continue;
        }

        // 4) Kalau gagal, forward ke Cloudflare 1.1.1.1
        if let Some(resp_msg) = forward_query(&buf[..len], "1.1.1.1:53").await {
            CACHE.lock().unwrap().set(&name, resp_msg.clone());

            let mut resp_buf = Vec::with_capacity(512);
            let mut encoder = BinEncoder::new(&mut resp_buf);
            resp_msg.emit(&mut encoder).unwrap();

            let _ = socket.send_to(&resp_buf, &src).await;
            continue;
        }
    }
}

