## 3. Isi `src/main.rs`

```rust
use std::net::Ipv4Addr;
use std::sync::Arc;

use tokio::net::UdpSocket;
use trust_dns_proto::op::{Message, MessageType, OpCode, Query};
use trust_dns_proto::rr::{Name, RData, Record, RecordType};
use trust_dns_proto::serialize::binary::{BinDecodable, BinEncodable};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let addr = "0.0.0.0:5353";
    let socket = UdpSocket::bind(addr).await?;
    println!("DNS server running on {}", addr);

    loop {
        let mut buf = [0u8; 512];
        let (len, src) = socket.recv_from(&mut buf).await?;

        let request = Message::from_bytes(&buf[..len])?;
        let query = request.queries().first().cloned();

        let mut response = Message::new();
        response.set_id(request.id());
        response.set_message_type(MessageType::Response);
        response.set_op_code(OpCode::Query);
        response.set_recursion_desired(true);
        response.set_recursion_available(true);

        if let Some(q) = query {
            let name = q.name().to_utf8();
            println!("Query: {}", name);

            // Contoh record statis
            if name == "example.local." && q.query_type() == RecordType::A {
                let record = Record::from_rdata(
                    Name::from_ascii("example.local.")?,
                    300,
                    RData::A(Ipv4Addr::new(10, 0, 0, 1)),
                );
                response.add_answer(record);
            }
        }

        let resp_bytes = response.to_bytes()?;
        socket.send_to(&resp_bytes, &src).await?;
    }
}
```

