## `wa-plugin.js` (Fastify Plugin + Route)

```js
import fp from 'fastify-plugin'
import * as baileys from 'baileys'
import { Client } from '@neoxr/wb'

export default fp(async function waPlugin(fastify) {
  let waClient

  const initClient = async (phone) => {
    if (waClient) return waClient

    waClient = new Client(
      {
        plugsdir: 'plugins',
        presence: true,
        online: true,
        bypass_disappearing: true,

        pairing: {
          state: true,      // pairing code (MD)
          number: phone,    // nomor dari API
          code: ''          // auto-generate
        },

        create_session: {
          type: 'local',
          session: `session-${phone}`,
          config: process.env.DATABASE_URL || ''
        },

        custom_id: `neoxr-${phone}`,
        engines: [baileys],
        debug: false
      },
      {
        version: [2, 3000, 1027023507],
        browser: ['Ubuntu', 'Firefox', '20.0.00'],
        shouldIgnoreJid: jid => /(newsletter|bot)/.test(jid)
      }
    )

    return waClient
  }

  /**
   * GET /api/v1/wa/:phone/code
   * generate pairing code
   */
  fastify.get('/api/v1/wa/:phone/code', async (req, reply) => {
    const { phone } = req.params

    if (!phone) {
      return reply.code(400).send({
        success: false,
        message: 'Phone number required'
      })
    }

    const wa = await initClient(phone)

    // tunggu socket siap
    await wa.connect()

    // ambil pairing code
    const pairingCode = await wa.getPairingCode(phone)

    return {
      success: true,
      phone,
      code: pairingCode
    }
  })

  fastify.decorate('wa', () => waClient)
}, {
  name: 'wa-plugin'
})
```

